import { clsx, type ClassValue } from "clsx";
import { extendTailwindMerge } from "tailwind-merge";

const twMerge = extendTailwindMerge({
  extend: { theme: { radius: ["control", "surface", "overlay"], shadow: ["overlay"] } },
});

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

import type { ComponentProps, ReactNode } from "react";
import { cn } from "./lib/cn";
import { Sparkline } from "./sparkline";

export type MetricProps = Omit<ComponentProps<"article">, "children"> & {
  label: string;
  value: ReactNode;
  context?: string;
  change?: string;
  series?: readonly number[];
};

export function Metric({
  label,
  value,
  context,
  change,
  series,
  className,
  ...props
}: MetricProps) {
  const tone = change?.startsWith("+")
    ? "text-success"
    : change?.startsWith("-")
      ? "text-warning"
      : "text-muted-foreground";
  return (
    <article
      data-slot="metric"
      className={cn(
        "flex min-w-0 flex-col rounded-overlay border border-border bg-background p-4",
        className,
      )}
      {...props}
    >
      <div className="flex items-start justify-between gap-3">
        <h3 className="text-xs leading-[18px] font-medium text-muted-foreground">
          {label}
        </h3>
        {change && (
          <p className={cn("text-xs tabular-nums", tone)}>{change}</p>
        )}
      </div>
      <p className="mt-3 text-2xl leading-8 font-medium tabular-nums">
        {value}
      </p>
      {context && (
        <p className="mt-1 text-xs text-muted-foreground">{context}</p>
      )}
      {series && series.length > 1 && (
        <Sparkline className="mt-3" values={series} label={`${label} trend`} />
      )}
    </article>
  );
}

import type { ComponentProps } from "react";
import { cn } from "./lib/cn";
import "./sparkline.css";

export type SparklineProps = Omit<ComponentProps<"svg">, "values"> & {
  values: readonly number[];
  label: string;
};

export function Sparkline({
  values,
  label,
  className,
  ...props
}: SparklineProps) {
  const width = 100;
  const height = 36;
  const min = Math.min(...values);
  const max = Math.max(...values);
  const span = max - min || 1;
  const points = values.map((value, index) => {
    const x =
      values.length === 1 ? width / 2 : (index / (values.length - 1)) * width;
    const y = height - ((value - min) / span) * (height - 4) - 2;
    return [x, y] as const;
  });
  const line = points
    .map(([x, y], index) => `${index === 0 ? "M" : "L"}${x},${y}`)
    .join(" ");
  const fill = `${line} L${width},${height} L0,${height} Z`;

  return (
    <svg
      data-slot="sparkline"
      viewBox={`0 0 ${width} ${height}`}
      preserveAspectRatio="none"
      role="img"
      aria-label={label}
      className={cn("h-9 w-full text-foreground", className)}
      {...props}
    >
      <path d={fill} fill="currentColor" opacity="0.08" />
      <path
        key={values.join(",")}
        data-slot="sparkline-line"
        d={line}
        fill="none"
        stroke="currentColor"
        strokeWidth="1.5"
        strokeLinecap="round"
        strokeLinejoin="round"
        vectorEffect="non-scaling-stroke"
        pathLength={100}
      />
    </svg>
  );
}

/* sparkline.tsx's styles; it imports this file. Edit freely. */
@layer theme, base, components, utilities;

@layer components {
  /* Drawn left to right by a clip, not a dash: with a non-scaling stroke Chrome ignores pathLength, so a dash pattern
     would leave a wide sparkline broken into segments. */
  [data-slot="sparkline-line"] {
    animation: caliper-sparkline var(--duration-deliberate) var(--ease-out) both;
  }

  @media (prefers-reduced-motion: reduce) {
    [data-slot="sparkline-line"] {
      animation: none;
      stroke-dashoffset: 0;
    }
  }
}

@keyframes caliper-sparkline {
  from {
    clip-path: inset(-10% 100% -10% 0);
  }
  to {
    clip-path: inset(-10% 0 -10% 0);
  }
}
